import {DOC_TYPE} from 'shared';
import {BaseLineMap} from '../types/base-line-map';
import {createDocRawArr} from './create-doc-raw-arr';

type MockedLine = {
    lineNr: number;
    type: string;
};

// builds one mocked line.
const line = (lineNr: number, type: string): MockedLine => ({lineNr, type});

// turns mocked lines into the BaseLineMap. Only creates necessary data.
const lines = (...mockedLines: MockedLine[]): BaseLineMap[] =>
    mockedLines.map(({lineNr, type}) => ({lineNr, type: type as DOC_TYPE, fields: []}));

// generated by claude. Comments and minor changes added by me.
describe('createDocRawArr', () => {
    it('creates one doc per HEAD', () => {
        const {docs} = createDocRawArr(lines(line(1, 'HEAD'), line(2, 'POS'), line(3, 'HEAD'), line(4, 'HEAD')));

        expect(docs).toHaveLength(3);
    });

    it('assigns TEXT and ALC before the first POS to the head', () => {
        const {docs} = createDocRawArr(lines(line(1, 'HEAD'), line(2, 'TEXT'), line(3, 'ALC'), line(4, 'POS')));

        expect(docs[0].texts).toHaveLength(1);
        expect(docs[0].alcs).toHaveLength(1);
        expect(docs[0].pos?.[0].texts).toHaveLength(0);
    });

    it('assigns TEXT and ALC after a POS to that POS', () => {
        const {docs} = createDocRawArr(lines(line(1, 'HEAD'), line(2, 'POS'), line(3, 'TEXT'), line(4, 'ALC')));

        expect(docs[0].texts).toHaveLength(0);
        expect(docs[0].pos?.[0].texts).toHaveLength(1);
        expect(docs[0].pos?.[0].alcs).toHaveLength(1);
    });

    it('assigns TEXT after the second POS to the second POS', () => {
        const {docs} = createDocRawArr(lines(line(1, 'HEAD'), line(2, 'POS'), line(3, 'POS'), line(4, 'TEXT')));

        expect(docs[0].pos?.[0].texts).toHaveLength(0);
        expect(docs[0].pos?.[1].texts).toHaveLength(1);
    });

    it('puts unknown types into unknownLines of the head only', () => {
        const {docs} = createDocRawArr(lines(line(1, 'HEAD'), line(2, 'POS'), line(3, 'XYZ')));

        expect(docs[0].unknownLines).toHaveLength(1);
        expect(docs[0].pos?.[0].unknownLines).toBeUndefined();
    });

    it('puts lines before the first HEAD into noHead and keeps the following doc intact', () => {
        const {docs, noHead} = createDocRawArr(lines(line(1, 'POS'), line(2, 'TEXT'), line(3, 'HEAD'), line(4, 'POS')));

        expect(noHead).toHaveLength(2);
        expect(docs).toHaveLength(1);
        expect(docs[0].pos).toHaveLength(1);
    });
});